fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    host::display::clear(0x0b0b0f);
    host::display::draw_string(40, 14, "MALE", 0x50a0e0, 2);
    host::display::draw_string(w - 110, 14, "FEMALE", 0xe080b0, 2);
    let bh: i32 = (h - 140) / 8;
    let mut i: i32 = 0;
    while i < 8 {
        let lv: i32 = 20 + (i * 29) % 50;
        let rv: i32 = 20 + (i * 17) % 50;
        let y: i32 = 60 + i * (bh + 6);
        host::display::fill_rect(cx - 30 - lv * 2, y, lv * 2, bh, 0x50a0e0);
        host::display::fill_rect(cx + 30, y, rv * 2, bh, 0xe080b0);
        host::display::draw_number(cx - 12, y + bh / 2 - 6, i + 1, 0xc0c0c0, 2);
        i = i + 1;
    }
    host::display::draw_line(cx - 30, 50, cx - 30, h - 60, 0x404048);
    host::display::draw_line(cx + 30, 50, cx + 30, h - 60, 0x404048);
    host::display::draw_string(40, h - 40, "AGE BAND PYRAMID", 0x606060, 1);
    host::display::present();
}
